      "CreatedOn": "WITH ProcessInstances AS ( SELECT pinst.proc_inst_id_, pinst.start_time_ AS case_creation_time, pinst.end_time_ AS closed_on, pinst.state_ FROM t17refined.camunda.act_hi_procinst pinst WHERE pinst.start_time_ >= CAST(:StartDate AS TIMESTAMP) AND pinst.start_time_ <= CAST(:EndDate AS TIMESTAMP) AND pinst.proc_def_key_ = ''AMLCases'' AND pinst.tenant_id_ = CAST(:tenantidstr AS VARCHAR) AND pinst.state_ = ''COMPLETED'' LIMIT :CountLimit ), LatestTask AS ( SELECT task.proc_inst_id_, task.id_ AS task_id, task.end_time_ AS task_end_time, task.assignee_, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM t17refined.camunda.act_hi_taskinst task WHERE task.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), StartStage AS ( SELECT startstage.proc_inst_id_, startstage.id_ AS start_stage_id, startstage.start_time_ AS start_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ ASC) AS rn FROM t17refined.camunda.act_hi_taskinst startstage WHERE startstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), EndStage AS ( SELECT endstage.proc_inst_id_, endstage.id_ AS end_stage_id, endstage.start_time_ AS end_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ DESC) AS rn FROM t17refined.camunda.act_hi_taskinst endstage WHERE endstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), OplogClaimStart AS ( SELECT oplogclaimstart.proc_inst_id_, oplogclaimstart.time_ AS start_time, ROW_NUMBER() OVER (PARTITION BY json_extract_scalar(oplogclaimstart.text_, ''$.id'') ORDER BY time_ DESC) AS rn FROM t17refined.camunda.act_hi_detail oplogclaimstart WHERE oplogclaimstart.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimstart.name_ = ''userActivity'' AND json_extract_scalar(oplogclaimstart.text_, ''$.action'') = ''Claim'' AND json_extract_scalar(oplogclaimstart.text_, ''$.id'') IN (SELECT start_stage_id FROM StartStage WHER