      "ClosedOn":  "WITH ProcessInstances AS ( SELECT pinst.proc_inst_id_, pinst.start_time_ AS case_creation_time, pinst.end_time_ AS closed_on, pinst.state_ FROM t8refined.camunda.act_hi_procinst pinst WHERE pinst.end_time_ >= CAST(:StartDate AS TIMESTAMP) AND pinst.end_time_ <= CAST(:EndDate AS TIMESTAMP) AND pinst.proc_def_key_ = ''AMLCases'' AND pinst.tenant_id_ = CAST(:tenantidstr AS VARCHAR) AND pinst.state_ = ''COMPLETED'' LIMIT :CountLimit ), LatestTask AS ( SELECT task.proc_inst_id_, task.id_ AS task_id, task.end_time_ AS task_end_time, task.assignee_, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY end_time_ DESC) AS rn FROM t8refined.camunda.act_hi_taskinst task WHERE task.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), StartStage AS ( SELECT startstage.proc_inst_id_, startstage.id_ AS start_stage_id, startstage.start_time_ AS start_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ ASC) AS rn FROM t8refined.camunda.act_hi_taskinst startstage WHERE startstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), EndStage AS ( SELECT endstage.proc_inst_id_, endstage.id_ AS end_stage_id, endstage.start_time_ AS end_stage_time, ROW_NUMBER() OVER (PARTITION BY proc_inst_id_ ORDER BY start_time_ DESC) AS rn FROM t8refined.camunda.act_hi_taskinst endstage WHERE endstage.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) ), OplogClaimStart AS ( SELECT oplogclaimstart.proc_inst_id_, oplogclaimstart.time_ AS start_time, ROW_NUMBER() OVER (PARTITION BY json_extract_scalar(oplogclaimstart.text_, ''$.id'') ORDER BY time_ DESC) AS rn FROM t8refined.camunda.act_hi_detail oplogclaimstart WHERE oplogclaimstart.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimstart.name_ = ''userActivity'' AND json_extract_scalar(oplogclaimstart.text_, ''$.action'') = ''Claim'' AND json_extract_scalar(oplogclaimstart.text_, ''$.id'') IN (SELECT start_stage_id FROM StartStage WHERE rn = 1) ), OplogClaimEnd AS ( SELECT oplogclaimend.proc_inst_id_, oplogclaimend.time_ AS end_time, ROW_NUMBER() OVER (PARTITION BY json_extract_scalar(oplogclaimend.text_, ''$.id'') ORDER BY time_ DESC) AS rn FROM t8refined.camunda.act_hi_detail oplogclaimend WHERE oplogclaimend.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND oplogclaimend.name_ = ''userActivity'' AND json_extract_scalar(oplogclaimend.text_, ''$.action'') = ''Claim'' AND json_extract_scalar(oplogclaimend.text_, ''$.id'') IN (SELECT end_stage_id FROM EndStage WHERE rn = 1) ), TransactionData AS ( SELECT Txn.proc_inst_id_, json_parse(from_utf8(Txnorg.bytes_)) AS transaction_json FROM t8refined.camunda.act_hi_varinst Txn LEFT JOIN t8refined.camunda.act_ge_bytearray Txnorg ON Txnorg.id_ = Txn.bytearray_id_ WHERE Txn.proc_inst_id_ IN (SELECT proc_inst_id_ FROM ProcessInstances) AND Txn.name_ = ''Transaction'' AND Txn.var_type_ = ''json'' ) SELECT TicketID.ticketid AS \\"Case ID\\", pinst.case_creation_time AS \\"Case creation time\\", Alert.text_ AS \\"Alert\\", json_extract_scalar(TransactionData.transaction_json, ''$.observations.payerVPA.externalId'') AS \\"Payer\\", json_extract_scalar(TransactionData.transaction_json, ''$.observations.payeeVPA.externalId'') AS \\"Payee\\", CASE WHEN typeof(TransactionData.transaction_json) = ''array'' THEN json_extract_scalar(json_array_get(TransactionData.transaction_json, 0), ''$.observations.vpa.vcexternaladdressid'') ELSE json_extract_scalar(TransactionData.transaction_json, ''$.observations.vpa.vcexternaladdressid'') END AS \\"VPA\\", CASE WHEN typeof(TransactionData.transaction_json) = ''array'' THEN json_extract_scalar(json_array_get(TransactionData.transaction_json, 0), ''$.observations.account.vcexternalaccountid'') ELSE json_extract_scalar(TransactionData.transaction_json, ''$.observations.account.vcexternalaccountid'') END AS \\"Account\\", Amount.double_ / 100 AS \\"Amount\\", OplogClaimStart.start_time AS \\"Start stage\\", OplogClaimEnd.end_